/**
 * `rapt launchpad` (D37): launchpad.json resolved against the applications generated by rapt
 * build (service paths, entity sets, roles, claims), its diagnostics, and the generated folder.
 */

import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import { main } from "../src/cli.js";
import { Diagnostics } from "../src/diagnostics.js";
import { generateLaunchpad } from "../src/gen/launchpad/index.js";
import { generateUi } from "../src/gen/ui/index.js";
import { loadProject } from "../src/input/project.js";
import { buildModel } from "../src/ir/builder.js";
import { resolveLaunchpad } from "../src/launchpad/config.js";
import type { RegisterResult } from "../src/launchpad/workspace.js";
import { FIXTURE_DIR } from "./helpers.js";

const SERVICE = "/sap/opu/odata4/sap/zrt_ui_travel_o4/srvd/sap/zrt_ui_travel/0001/";

let work: string;

/** The part of `rapt build` the launchpad reads: model/model.json and ui/manifest.json. */
function writeApplication(dir: string): void {
  const { model } = buildModel(loadProject(FIXTURE_DIR));
  mkdirSync(path.join(dir, "model"), { recursive: true });
  writeFileSync(path.join(dir, "model", "model.json"), JSON.stringify(model));
  mkdirSync(path.join(dir, "ui"), { recursive: true });
  writeFileSync(path.join(dir, "ui", "manifest.json"), generateUi(model!).find((f) => f.path === "manifest.json")?.content ?? "");
}

beforeAll(() => {
  work = mkdtempSync(path.join(tmpdir(), "rapt-launchpad-test-"));
  writeApplication(path.join(work, "build", "travel"));
});

afterAll(() => rmSync(work, { recursive: true, force: true }));

const TRAVEL = { id: "travel", build: "build/travel", url: "http://localhost:8080" };

function resolve(source: unknown): { diagnostics: Diagnostics; result: ReturnType<typeof resolveLaunchpad> } {
  const file = path.join(work, `launchpad-${Math.random().toString(36).slice(2, 8)}.json`);
  writeFileSync(file, typeof source === "string" ? source : JSON.stringify(source));
  const diagnostics = new Diagnostics();
  return { diagnostics, result: resolveLaunchpad(file, diagnostics) };
}

const codes = (d: Diagnostics): string[] => d.items.map((i) => `${i.severity} ${i.code}`);

describe("launchpad.json", () => {
  it("resolves the tiles against the generated application", () => {
    const { diagnostics, result } = resolve({
      title: "Travel Agency",
      apps: [TRAVEL],
      groups: [
        {
          title: "Travels",
          tiles: [
            { app: "travel", intent: "Travel-manage", icon: "sap-icon://flight", count: "Travel", roles: ["travel_viewer", "travel_manager"] },
            { title: "Open", app: "travel", count: { entitySet: "Travel", filter: "OverallStatus eq 'O'" } },
            { title: "Help", url: "https://example.org/help" },
            { title: "Help", url: "/apps/travel/ui/index.html#/Travel/new" },
          ],
        },
      ],
    });
    expect(diagnostics.items).toEqual([]);
    const model = result!.model;
    expect(model.apps).toEqual([{ id: "travel", title: "Travels", url: "http://localhost:8080/", servicePaths: [SERVICE] }]);
    const [manage, open, help, internal] = model.groups[0]!.tiles;
    // the title of the UI of the application, the id of the intent
    expect(manage).toEqual({ id: "travel-manage", title: "Travels", target: "/apps/travel/ui/index.html", external: false, roles: ["travel_viewer", "travel_manager"], icon: "sap-icon://flight", intent: "Travel-manage", app: "travel", count: `${SERVICE}Travel/$count` });
    expect(open?.count).toBe(`${SERVICE}Travel/$count?$filter=OverallStatus%20eq%20'O'`);
    expect(open?.roles).toEqual([]);
    expect(help).toMatchObject({ id: "help", target: "https://example.org/help", external: true });
    expect(internal).toMatchObject({ id: "help-2", external: false });
    // the claims and the roles of rapt/authorizations.json of the application
    expect(model.claims).toEqual(["agency"]);
    expect(model.roles.map((r) => r.name)).toEqual(["travel_manager", "travel_agent", "travel_viewer"]);
  });

  it("resolves spaces and pages (D48)", () => {
    const { diagnostics, result } = resolve({
      title: "Travel Agency",
      apps: [TRAVEL],
      spaces: [
        {
          title: "Travels",
          pages: [
            { title: "Daily work", sections: [{ title: "Manage", tiles: [{ app: "travel", intent: "Travel-manage" }] }] },
            { title: "Analysis", sections: [{ title: "Open", tiles: [{ title: "Open", app: "travel", count: { entitySet: "Travel", filter: "OverallStatus eq 'O'" } }] }] },
          ],
        },
        { title: "Administration", roles: ["travel_manager"], pages: [{ title: "Help", sections: [{ title: "Links", tiles: [{ title: "Help", url: "https://example.org" }] }] }] },
      ],
    });
    expect(diagnostics.items).toEqual([]);
    const model = result!.model;
    expect(model.spaces?.map((s) => [s.id, s.title, s.roles, s.pages.map((p) => p.id)])).toEqual([
      ["travels", "Travels", [], ["travels-daily-work", "travels-analysis"]],
      ["administration", "Administration", ["travel_manager"], ["administration-help"]],
    ]);
    // every section is also a group (intents, search)
    expect(model.groups.map((g) => g.title)).toEqual(["Manage", "Open", "Links"]);
    expect(codes(resolve({ apps: [TRAVEL], spaces: [{ title: "Bad" }] }).diagnostics)).toEqual(["error LPD008"]);
  });

  it("reports the errors of the content", () => {
    const { diagnostics } = resolve({
      apps: [TRAVEL, { ...TRAVEL }, { id: "Bad id", url: "http://x" }, { id: "nourl" }, { id: "missing", build: "build/none", url: "http://localhost:8081" }],
      groups: [
        {
          title: "G",
          tiles: [
            { title: "Unknown app", app: "flights" },
            { title: "Both", app: "travel", url: "https://example.org" },
            { title: "Neither" },
            { title: "Bad intent", app: "travel", intent: "manage" },
            { title: "Bad count", app: "travel", count: "Flights" },
            { title: "Count without app", url: "https://example.org", count: "Travel" },
            { title: "Unknown role", app: "travel", roles: ["travel_admin"] },
          ],
        },
        { tiles: [] },
      ],
    });
    expect(codes(diagnostics)).toEqual([
      "error LPD001", // two applications travel
      "error LPD001", // Bad id
      "error LPD001", // no url
      "error LPD003", // build/none
      "warning LPD003", // missing: no service known
      "error LPD002", // unknown app
      "error LPD002", // both
      "error LPD002", // neither
      "error LPD004", // bad intent
      "error LPD006", // unknown entity set
      "error LPD006", // count without app
      "warning LPD007", // unknown role
      "error LPD001", // group without title
    ]);
    expect(diagnostics.items.find((d) => d.code === "LPD006")?.message).toContain("no entity set Flights");
  });

  it("refuses services the launchpad cannot route", () => {
    const { diagnostics } = resolve({
      apps: [TRAVEL, { id: "copy", url: "http://localhost:8081", servicePaths: [SERVICE] }, { id: "odd", url: "http://localhost:8082", servicePaths: ["/ui/odata/"] }],
      groups: [],
    });
    expect(codes(diagnostics)).toEqual(["error LPD005", "error LPD005"]);
    expect(diagnostics.items[0]?.message).toContain("both serve");
    expect(diagnostics.items[1]?.message).toContain("below /ui");
  });

  it("reports a file that is not a launchpad", () => {
    expect(codes(resolve("{ not json").diagnostics)).toEqual(["error LPD001"]);
    expect(codes(resolve({ title: "No groups" }).diagnostics)).toEqual(["error LPD001"]);
  });
});

describe("the generated launchpad", () => {
  it("writes the server, the configuration, the UI, Docker and the realm", () => {
    const file = path.join(work, "launchpad.json");
    writeFileSync(file, JSON.stringify({ title: "Travel Agency", apps: [TRAVEL], groups: [{ title: "Travels", tiles: [{ app: "travel", intent: "Travel-manage", count: "Travel", roles: ["travel_viewer"] }] }] }));
    const result = generateLaunchpad(file, { outDir: path.join(work, "out", "launchpad") });
    expect(result.diagnostics.items).toEqual([]);
    const content = (name: string): string => result.files.find((f) => f.path === name)?.content ?? "";
    for (const name of ["package.json", "server.mjs", "launchpad/config.json", "ui/index.html", "ui/manifest.json", "ui/Component.js", "ui/view/Launchpad.view.xml", "ui/controller/Launchpad.controller.js", "ui/logo.svg", "Dockerfile", "manifest.yml", ".cfignore", "docker-compose.yml", "keycloak/rapt-realm.json", ".env.example", "README.md", "vendor/open-rap-runtime/package.json"]) {
      expect(content(name), name).not.toBe("");
    }
    expect(JSON.parse(content("package.json"))).toMatchObject({ name: "travel-agency-launchpad", dependencies: { "@open-rap-runtime/runtime": "file:vendor/open-rap-runtime" } });
    expect(content("server.mjs")).toContain("startLaunchpad");
    // the application, built from its folder next to the launchpad, behind it with the same login
    const compose = content("docker-compose.yml");
    expect(compose).toContain("  travel:\n    build: ../../build/travel\n");
    expect(compose).toContain("APP_TRAVEL_URL: http://travel:8080/");
    expect(compose).toContain("OIDC_CLIENT_ID: rapt-launchpad");
    expect(content(".env.example")).toContain("APP_TRAVEL_URL=http://localhost:8080/");
    const realm = JSON.parse(content("keycloak/rapt-realm.json")) as { clients: Array<{ clientId: string; redirectUris: string[]; protocolMappers?: Array<{ name: string }> }>; users: Array<{ realmRoles: string[] }> };
    expect(realm.clients[0]).toMatchObject({ clientId: "rapt-launchpad", redirectUris: ["http://localhost:8090/auth/callback"] });
    expect(realm.clients[0]?.protocolMappers?.map((m) => m.name)).toEqual(["agency"]);
    expect(realm.users[0]?.realmRoles).toEqual(["rapt_user", "travel_manager", "travel_agent", "travel_viewer"]);
    expect(content("README.md")).toContain("| Travels | Travels | `Travel-manage` | `travel_viewer` |");
  });
});

describe("rapt launchpad", () => {
  let out: string[];
  let err: string[];
  beforeEach(() => {
    out = [];
    err = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      out.push(String(chunk));
      return true;
    });
    vi.spyOn(process.stderr, "write").mockImplementation((chunk) => {
      err.push(String(chunk));
      return true;
    });
  });
  afterEach(() => vi.restoreAllMocks());

  it("writes the launchpad, and fails on the errors of launchpad.json", async () => {
    const file = path.join(work, "cli.json");
    writeFileSync(file, JSON.stringify({ apps: [TRAVEL], groups: [{ title: "Travels", tiles: [{ app: "travel" }] }] }));
    const dir = path.join(work, "cli-out");
    expect(await main(["launchpad", file, "--out", dir])).toBe(0);
    expect(existsSync(path.join(dir, "launchpad", "config.json"))).toBe(true);
    expect(JSON.parse(readFileSync(path.join(dir, "launchpad", "config.json"), "utf8")).title).toBe("Launchpad");
    expect(out.join("")).toContain("files written to");

    writeFileSync(file, JSON.stringify({ apps: [TRAVEL], groups: [{ title: "Travels", tiles: [{ app: "flights" }] }] }));
    expect(await main(["launchpad", file, "--out", path.join(work, "cli-failed")])).toBe(1);
    expect(err.join("")).toContain("error LPD002");
    expect(existsSync(path.join(work, "cli-failed"))).toBe(false);
    expect(await main(["launchpad", file])).toBe(2);
  });
});

describe("the launchpad of the workspace (D69)", () => {
  let out: string[];
  let ws: string;
  const copy = (name: string): string => {
    const dir = path.join(ws, name);
    cpSync(FIXTURE_DIR, dir, { recursive: true, filter: (f) => ![".rapt", "out"].includes(path.relative(FIXTURE_DIR, f).split(path.sep)[0] ?? "") });
    return dir;
  };
  const last = <T>(): T => JSON.parse(out.join("").trim().split("\n").pop() ?? "") as T;
  beforeEach(() => {
    out = [];
    ws = mkdtempSync(path.join(tmpdir(), "rapt-workspace-test-"));
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      out.push(String(chunk));
      return true;
    });
    vi.spyOn(process.stderr, "write").mockImplementation(() => true);
  });
  afterEach(() => {
    vi.restoreAllMocks();
    rmSync(ws, { recursive: true, force: true });
  });

  it("creates one launchpad titled Launchpad next to the projects, and adds each application once", async () => {
    const travel = copy("travel");
    const flights = copy("flights");
    expect(await main(["launchpad", "add", travel, "--json"])).toBe(0);
    expect(last<RegisterResult>()).toMatchObject({ file: path.join(ws, "launchpad.json"), created: true, added: true, app: { id: "travel", source: "travel" } });
    const file = path.join(ws, "launchpad.json");
    const edited = JSON.parse(readFileSync(file, "utf8"));
    expect(edited.title).toBe("Launchpad");
    edited.groups[0].tiles[0].title = "Mes voyages";
    writeFileSync(file, JSON.stringify(edited));

    expect(await main(["launchpad", "add", travel, "--json"])).toBe(0);
    expect(last<RegisterResult>()).toMatchObject({ created: false, added: false });
    // the second project finds the launchpad of the first one
    expect(await main(["launchpad", "add", flights, "--json"])).toBe(0);
    expect(last<RegisterResult>()).toMatchObject({ file, created: false, added: true, app: { id: "flights", source: "flights", url: "http://localhost:8082/" } });

    const source = JSON.parse(readFileSync(file, "utf8"));
    expect(source.apps.map((a: { id: string }) => a.id)).toEqual(["travel", "flights"]);
    expect(source.groups).toHaveLength(1);
    expect(source.groups[0].tiles).toEqual([
      expect.objectContaining({ title: "Mes voyages", app: "travel", intent: "Travel-manage", count: "Travel" }),
      expect.objectContaining({ app: "flights", intent: "Travel2-manage" }),
    ]);
    expect(existsSync(path.join(travel, "launchpad.json"))).toBe(false);
  });

  it("adds the application on rapt new and rapt floorplan, unless --no-launchpad", async () => {
    const orders = path.join(ws, "orders");
    expect(await main(["new", orders, "Order", "--prefix", "ZOR", "--json"])).toBe(0);
    expect(last<{ launchpad: RegisterResult }>().launchpad).toMatchObject({ file: path.join(ws, "launchpad.json"), created: true, added: true, app: { id: "orders" } });

    expect(await main(["new", path.join(ws, "draft"), "Draft", "--prefix", "ZDR", "--no-launchpad", "--json"])).toBe(0);
    expect(last<{ launchpad?: unknown }>().launchpad).toBeUndefined();

    const travel = copy("travel");
    const custom = path.join(ws, "custom", "launchpad.json");
    expect(await main(["floorplan", travel, "Travel", "worklist", "--launchpad", custom, "--json"])).toBe(0);
    expect(last<{ launchpad: RegisterResult }>().launchpad).toMatchObject({ file: custom, created: true, app: { source: "../travel" }, tile: { intent: "Travel-process" } });
    expect(JSON.parse(readFileSync(path.join(ws, "launchpad.json"), "utf8")).apps.map((a: { id: string }) => a.id)).toEqual(["orders"]);
  });

  it("builds the applications of their sources with the launchpad", async () => {
    copy("travel");
    const file = path.join(ws, "launchpad.json");
    writeFileSync(file, JSON.stringify({ title: "Launchpad", apps: [{ id: "travel", source: "travel", url: "http://localhost:8081/" }], groups: [{ title: "Applications", tiles: [{ app: "travel", count: "Travel" }] }] }));
    const dir = path.join(ws, "out");
    expect(await main(["launchpad", file, "--out", dir, "--json"])).toBe(0);
    expect(last<{ ok: boolean; apps: unknown[] }>()).toMatchObject({ ok: true, apps: [{ id: "travel", out: path.join(dir, "apps", "travel") }] });
    expect(existsSync(path.join(dir, "apps", "travel", "server.mjs"))).toBe(true);
    expect(readFileSync(path.join(dir, "docker-compose.yml"), "utf8")).toContain("build: apps/travel");
    expect(readFileSync(path.join(dir, ".dockerignore"), "utf8")).toContain("apps");
    expect(JSON.parse(readFileSync(path.join(dir, "launchpad", "config.json"), "utf8")).apps).toEqual([expect.objectContaining({ id: "travel", title: "Travels" })]);
  });

  it("refuses an application with both its sources and its build", () => {
    const { diagnostics } = resolve({ apps: [{ ...TRAVEL, source: "travel" }], groups: [] });
    expect(codes(diagnostics)).toContain("error LPD009");
  });
});
